const r = $input.first().json;
const msg = $('Mensaje al bot de logística').first().json.message;
const usuario = $('Validar usuario').first().json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const texto = String(r.output || 'No pude generar una respuesta.').trim();
// Partir en bloques de hasta 4000 caracteres, cortando en saltos de línea
const partes = [];
let resto = texto;
while (resto.length > 4000) {
  let corte = resto.lastIndexOf('\n', 4000);
  if (corte < 1000) corte = 4000;
  partes.push(resto.slice(0, corte));
  resto = resto.slice(corte).replace(/^\n+/, '');
}
partes.push(resto);
// Herramientas usadas
const herramientas = [...new Set((r.intermediateSteps || []).map(s => s && s.action && s.action.tool).filter(Boolean))];
// Tokens: se leen de las corridas del modelo (si n8n no las expone, quedan en null)
let tin = null, tout = null;
try {
  for (let i = 0; i < 20; i++) {
    let items;
    try { items = $('Claude Haiku').all(0, i); } catch (e) { break; }
    if (!items || !items.length) break;
    for (const it of items) {
      const u = it.json.tokenUsage || it.json.tokenUsageEstimate || {};
      if (u.promptTokens != null) tin = (tin || 0) + u.promptTokens;
      if (u.completionTokens != null) tout = (tout || 0) + u.completionTokens;
    }
  }
} catch (e) {}
const registro = {
  bot: 'logistica',
  usuario_id: usuario.id || null,
  chat_id: msg.chat.id,
  pregunta: msg.text || null,
  herramientas,
  tokens_entrada: tin,
  tokens_salida: tout,
  error: null
};
return partes.map(p => ({ json: { chat_id: String(msg.chat.id), texto: esc(p), registro } }));

